function reducer(state, action) {
  switch (action.type) {
    case 'add':    return { ...state, count: state.count + 1 };
    case 'remove': return { ...state, count: state.count - 1 };
    case 'reset':  return { count: 0 };
    default: throw new Error();
  }
}

